patch:
--- zshrc.before
+++ zshrc.current
@@ -68,7 +68,7 @@
 }

 claude() {
-  _cc_launch "$@"
+  cc_fast_run _cc_launch -- "$@"
 }

 claude-official() {
@@ -299,19 +299,26 @@
   fi
 }

-cc() {
+_cc_native() {
+  local model="$1" effort="$2"; shift 2
   local dir; dir=$(_cc_dir "$1"); [[ -n $dir ]] && shift
-  _cc_exec "$dir" "$@"
+  if [[ -n "$model" ]]; then
+    _cc_exec "$dir" --model "$model" --effort "$effort" "$@"
+  else
+    _cc_exec "$dir" "$@"
+  fi
 }

+cc() {
+  cc_fast_run _cc_native '' '' -- "$@"
+}
+
 ccopus() {
-  local dir; dir=$(_cc_dir "$1"); [[ -n $dir ]] && shift
-  _cc_exec "$dir" --model 'opus[1m]' --effort xhigh "$@"
+  cc_fast_run _cc_native 'opus[1m]' xhigh -- "$@"
 }

 ccfable() {
-  local dir; dir=$(_cc_dir "$1"); [[ -n $dir ]] && shift
-  _cc_exec "$dir" --model fable --effort medium "$@"
+  cc_fast_run _cc_native fable medium -- "$@"
 }

 # 切換 cc-current 這個 selector symlink 指向哪個 binary，一次改動全部啟動器
